import { Schema } from "effect";

import { Capability } from "./feature-manifest.ts";

/**
 * A breaking change to a capability kind's authoring contract that did **not**
 * remove the kind — the kind still loads, but its required shape changed (RFC
 * 0002 Feature Compatibility and Migration). `since` is the CLI version that
 * introduced the rule; `rule` is a stable id the migration report correlates
 * against a live loader diagnostic; `summary` is the human one-liner.
 *
 * The `rule` id MUST correspond to a diagnostic the contribution loader already
 * emits (e.g. the `schedule` loader's "must export a named schedule, not a
 * default export"), so the report can match a live failure to the version that
 * introduced the rule. This is what makes the **sniffer case** visible — a
 * kind-presence diff alone reports the kind as still-present and misses it.
 */
interface CapabilityShapeChange {
  readonly since: string;
  readonly rule: string;
  readonly summary: string;
}

/**
 * The lifecycle of one capability kind across CLI versions (RFC 0002 Feature
 * Compatibility and Migration). `since` is the CLI version that introduced the
 * kind; `deprecatedIn` (optional) marks it still loadable but scheduled for
 * removal (using it warns); `removedIn` (optional) marks it no longer loadable
 * as of that version (using it is a blocker); `shapeChanges` (optional) lists
 * breaking authoring-shape changes within the kind that did not remove it.
 *
 * This is **declared, not inferred**: the migration diff names what was dropped
 * from this registry, and it is the source of truth. The values are **CLI versions** — the same axis the
 * workspace records via the `routekit-eval.md` `version` stamp — so the migration report
 * can compare the workspace's generating CLI version against the running one.
 */
interface CapabilityLifecycle {
  readonly since: string;
  readonly deprecatedIn?: string;
  readonly removedIn?: string;
  readonly shapeChanges?: readonly CapabilityShapeChange[];
}

const SEMVER_PATTERN = /^\d+\.\d+\.\d+(?:[-+].+)?$/u;
// Without a `patterns` hint this filter is opaque to generation: fast-check
// samples plain strings and rejects nearly all of them (a random string
// almost never looks like `\d+\.\d+\.\d+`), which is generate-then-reject
// until exhaustion rather than a real hang — confirmed by sampling this
// schema directly, which times out, while `Schema.toArbitrary` itself
// returns instantly. The hint reuses the same pattern so the generator and
// the filter can never drift apart.
const SemVerString = Schema.String.check(
  Schema.makeFilter(
    (value) =>
      SEMVER_PATTERN.test(value)
        ? undefined
        : `must be a SemVer-shaped version, got "${value}"`,
    {
      arbitrary: {
        constraint: {
          patterns: [SEMVER_PATTERN.source],
        },
      },
    }
  )
);

export const CapabilityShapeChangeSchema = Schema.Struct({
  since: SemVerString,
  rule: Schema.NonEmptyString,
  summary: Schema.NonEmptyString,
});

export const CapabilityLifecycleSchema = Schema.Struct({
  since: SemVerString,
  deprecatedIn: Schema.optionalKey(SemVerString),
  removedIn: Schema.optionalKey(SemVerString),
  shapeChanges: Schema.optionalKey(Schema.Array(CapabilityShapeChangeSchema)),
});

/**
 * The lifecycle of every capability kind. Every member of the closed
 * `Capability` enum MUST have an entry (enforced by the colocated test), so the
 * migration diff can always resolve a `since`/`deprecatedIn`/`removedIn` for any
 * kind a workspace records. `since` is the CLI version that introduced the kind;
 * none is deprecated or removed yet, so entries gain
 * `deprecatedIn`/`removedIn` as the CLI evolves.
 *
 * `schedule` carries the first declared `shapeChanges` rule: it was born in
 * CLI 0.27.0 requiring the schedule to be a named `export const schedule` —
 * never a default export.
 * A workspace generated by an older CLI (`version` < 0.27.0) whose `schedule.ts`
 * still uses a default export therefore fails to load on a modern CLI; the
 * migration report correlates that live loader failure (the `schedule` loader's
 * "must export a named schedule, not a default export" diagnostic) with this
 * rule and reports a `BreakingShapeChange` blocker — the RFC 0002 sniffer case.
 *
 * `api` carries the second: 0.43.0 reshaped the export from an arbitrary bag to
 * the closed `{ exports?, routes? }` shape.
 * A pre-0.43.0 workspace whose `api` export carries arbitrary top-level keys
 * fails the closed-shape decode; the report correlates that loader failure with
 * this rule the same way.
 *
 * `command` carries the third: 0.85.0 requires a standalone `command.ts` to be a
 * named `export const command`, never a default export, mirroring `schedule`'s
 * own rule above. A pre-0.85.0 workspace with a
 * default-exported `command.ts` fails to load; the report correlates that
 * loader failure with this rule the same way.
 */
export const CAPABILITY_LIFECYCLE: Readonly<
  Record<Capability, CapabilityLifecycle>
> = {
  [Capability.Harness]: { since: "0.2.0" },
  [Capability.Chat]: { since: "0.2.0" },
  [Capability.Schedule]: {
    since: "0.27.0",
    shapeChanges: [
      {
        since: "0.27.0",
        rule: "named-export-required",
        summary:
          "schedule must be a named `export const schedule`, not a default export",
      },
    ],
  },
  [Capability.Api]: {
    since: "0.2.0",
    shapeChanges: [
      {
        since: "0.43.0",
        rule: "closed-two-key-shape",
        summary:
          "api must be `{ exports?, routes? }`; arbitrary top-level keys are rejected (move them under `exports`)",
      },
    ],
  },
  [Capability.Hooks]: { since: "0.80.0" },
  [Capability.Prompt]: { since: "0.3.0" },
  [Capability.Skill]: { since: "0.2.0" },
  [Capability.Command]: {
    since: "0.58.0",
    shapeChanges: [
      {
        since: "0.85.0",
        rule: "command-named-export-required",
        summary:
          "a standalone command.ts must be a named `export const command`, not a default export",
      },
    ],
  },
};

/**
 * Module-level authoring-shape changes — breaking changes to `feature.ts`
 * itself rather than to one capability's value shape, so they cannot live in
 * {@link CAPABILITY_LIFECYCLE}, which is keyed per `Capability`. Reuses
 * {@link CapabilityShapeChange} verbatim; the migration report matches these
 * against the module-level `ROUTEKIT_EVAL_BOOT_IMPORT_FEATURE_MODULE` diagnostic instead
 * of a capability-scoped `ROUTEKIT_EVAL_BOOT_IMPORT_<KIND>` one.
 *
 * The one entry declared here reverses ROUTEKIT_EVAL-167: 0.85.0 removes the whole-module
 * `export default { ... } satisfies FeatureModule` form.
 * A workspace scaffolded against 0.58.0–0.84.x whose `feature.ts` still uses
 * that default-export form fails to load on a modern CLI; the migration report
 * correlates that live loader failure with this rule and reports a
 * `BreakingShapeChange` blocker, the same sniffer case as the per-capability
 * rules above.
 */
export const FEATURE_MODULE_SHAPE_CHANGES: readonly CapabilityShapeChange[] = [
  {
    since: "0.85.0",
    rule: "feature-module-named-exports-required",
    summary:
      "feature.ts must export each contribution by name (e.g. `export const harness = ...`); a whole-module `export default {...} satisfies FeatureModule` is no longer recognized",
  },
];

export type { CapabilityShapeChange, CapabilityLifecycle };
